/* WARNING! Mostly generated by LLM
 *
 * cpu_features.h — comprehensive x86/x86-64 CPU feature detection via CPUID
 *
 * Usage:
 *
 *   #define CPU_FEATURES_PRINT
 *   #include "x86_cpu_features.h"
 *
 *   CpuFeatures cpu = cpu_detect();
 *   cpu_features_print(&cpu);
 *   CpuCacheInfo cpuCache = cpu_cache_detect();
 *   cpu_cache_print(&cpuCache);
 *   if (cpu.avx2 && cpu.fma) { ... }
 *
 * Compilers:	GCC, Clang, MSVC
 * Platforms:	Linux, Windows, macOS (x86/x86-64 only)
 * Author:		Gleb Konstantinovich - 2025
 */

#pragma once

#include <stdint.h>
#include <string.h>  /* memset */

#if defined(_MSC_VER)
#  include <intrin.h>
#else
#  include <cpuid.h>
#endif

/* -------------------------------------------------------------------------
 * Portable CPUID wrappers
 * ------------------------------------------------------------------------- */

static inline void
_cpuid(uint32_t leaf, uint32_t *eax, uint32_t *ebx, uint32_t *ecx, uint32_t *edx)
{
#if defined(_MSC_VER)
    int r[4];
    __cpuid(r, (int)leaf);
    *eax = (uint32_t)r[0]; *ebx = (uint32_t)r[1];
    *ecx = (uint32_t)r[2]; *edx = (uint32_t)r[3];
#else
    __cpuid(leaf, *eax, *ebx, *ecx, *edx);
#endif
}

static inline void
_cpuidex(uint32_t leaf, uint32_t subleaf,
         uint32_t *eax, uint32_t *ebx, uint32_t *ecx, uint32_t *edx)
{
#if defined(_MSC_VER)
    int r[4];
    __cpuidex(r, (int)leaf, (int)subleaf);
    *eax = (uint32_t)r[0]; *ebx = (uint32_t)r[1];
    *ecx = (uint32_t)r[2]; *edx = (uint32_t)r[3];
#else
    __cpuid_count(leaf, subleaf, *eax, *ebx, *ecx, *edx);
#endif
}

/* -------------------------------------------------------------------------
 * Feature struct — 1 бит на фичу
 * ------------------------------------------------------------------------- */

typedef struct {

    /* --- Vendor info --- */
    char vendor[13];     /* "GenuineIntel" / "AuthenticAMD" / "HygonGenuine" etc. */
    char brand[49];      /* "Intel(R) Core(TM) i9-..." */
    int  is_intel;
    int  is_amd;

    /* --- Leaf 1 EDX --- */
    int fpu;             /* x87 FPU on-chip */
    int vme;             /* Virtual 8086 Mode Extensions */
    int de;              /* Debugging Extensions */
    int pse;             /* Page Size Extension */
    int tsc;             /* Time Stamp Counter (RDTSC) */
    int msr;             /* Model Specific Registers */
    int pae;             /* Physical Address Extension */
    int mce;             /* Machine Check Exception */
    int cx8;             /* CMPXCHG8B */
    int apic;            /* APIC on-chip */
    int sep;             /* SYSENTER/SYSEXIT */
    int mtrr;            /* Memory Type Range Registers */
    int pge;             /* Page Global Enable */
    int mca;             /* Machine Check Architecture */
    int cmov;            /* Conditional Move Instructions */
    int pat;             /* Page Attribute Table */
    int pse36;           /* 36-bit Page Size Extension */
    int psn;             /* Processor Serial Number (Pentium III) */
    int clfsh;           /* CLFLUSH instruction */
    int ds;              /* Debug Store */
    int acpi;            /* Thermal Monitor and Software Controlled Clock */
    int mmx;             /* MMX Technology */
    int fxsr;            /* FXSAVE/FXRSTOR */
    int sse;             /* SSE */
    int sse2;            /* SSE2 */
    int ss;              /* Self Snoop */
    int htt;             /* Hyper-Threading Technology */
    int tm;              /* Thermal Monitor */
    int pbe;             /* Pending Break Enable */

    /* --- Leaf 1 ECX --- */
    int sse3;            /* SSE3 (Prescott New Instructions) */
    int pclmulqdq;       /* Carryless Multiplication (PCLMULQDQ) */
    int dtes64;          /* 64-bit DS Area */
    int monitor;         /* MONITOR/MWAIT */
    int ds_cpl;          /* CPL Qualified Debug Store */
    int vmx;             /* Virtual Machine Extensions (Intel VT-x) */
    int smx;             /* Safer Mode Extensions (TXT) */
    int est;             /* Enhanced Intel SpeedStep */
    int tm2;             /* Thermal Monitor 2 */
    int ssse3;           /* Supplemental SSE3 */
    int cnxt_id;         /* L1 Context ID */
    int sdbg;            /* Silicon Debug Interface */
    int fma;             /* FMA3 (256-bit) */
    int cx16;            /* CMPXCHG16B */
    int xtpr;            /* xTPR Update Control */
    int pdcm;            /* Perfmon and Debug Capability */
    int pcid;            /* Process Context Identifiers */
    int dca;             /* Direct Cache Access */
    int sse4_1;          /* SSE4.1 */
    int sse4_2;          /* SSE4.2 */
    int x2apic;          /* Extended xAPIC Support */
    int movbe;           /* MOVBE instruction */
    int popcnt;          /* POPCNT instruction */
    int tsc_deadline;    /* TSC Deadline Timer */
    int aes;             /* AES New Instructions (AESNI) */
    int xsave;           /* XSAVE/XRSTOR/XSETBV/XGETBV */
    int osxsave;         /* OS has enabled XSETBV/XGETBV (CR4.OSXSAVE) */
    int avx;             /* AVX (256-bit) */
    int f16c;            /* 16-bit float convert (VCVTPH2PS/VCVTPS2PH) */
    int rdrnd;           /* RDRAND hardware RNG */
    int hypervisor;      /* Running under hypervisor */

    /* --- Leaf 7, subleaf 0, EBX --- */
    int fsgsbase;        /* RDFSBASE/RDGSBASE/WRFSBASE/WRGSBASE */
    int ia32_tsc_adjust; /* IA32_TSC_ADJUST MSR */
    int sgx;             /* Software Guard Extensions */
    int bmi1;            /* Bit Manipulation Instruction Set 1 */
    int hle;             /* Hardware Lock Elision (TSX) */
    int avx2;            /* AVX2 (256-bit integer SIMD) */
    int fdp_excptn_only; /* FDP_EXCPTN_ONLY */
    int smep;            /* Supervisor Mode Execution Prevention */
    int bmi2;            /* Bit Manipulation Instruction Set 2 */
    int erms;            /* Enhanced REP MOVSB/STOSB */
    int invpcid;         /* INVPCID instruction */
    int rtm;             /* Restricted Transactional Memory (TSX) */
    int mpx;             /* Memory Protection Extensions */
    int avx512f;         /* AVX-512 Foundation */
    int avx512dq;        /* AVX-512 Doubleword and Quadword */
    int rdseed;          /* RDSEED instruction */
    int adx;             /* Multi-Precision Add-Carry (ADX) */
    int smap;            /* Supervisor Mode Access Prevention */
    int avx512ifma;      /* AVX-512 Integer Fused Multiply-Add */
    int clflushopt;      /* CLFLUSHOPT instruction */
    int clwb;            /* Cache Line Write Back */
    int intel_pt;        /* Intel Processor Trace */
    int avx512pf;        /* AVX-512 Prefetch (Xeon Phi only) */
    int avx512er;        /* AVX-512 Exponential and Reciprocal (Xeon Phi only) */
    int avx512cd;        /* AVX-512 Conflict Detection */
    int sha;             /* SHA-1 and SHA-256 extensions */
    int avx512bw;        /* AVX-512 Byte and Word */
    int avx512vl;        /* AVX-512 Vector Length Extensions */

    /* --- Leaf 7, subleaf 0, ECX --- */
    int prefetchwt1;     /* PREFETCHWT1 (Xeon Phi only) */
    int avx512vbmi;      /* AVX-512 Vector Byte Manipulation */
    int umip;            /* User-Mode Instruction Prevention */
    int pku;             /* Protection Keys for User-mode pages */
    int ospke;           /* OS Protection Keys Enable */
    int waitpkg;         /* TPAUSE/UMONITOR/UMWAIT */
    int avx512vbmi2;     /* AVX-512 Vector Byte Manipulation 2 */
    int cet_ss;          /* Control-flow Enforcement: Shadow Stack */
    int gfni;            /* Galois Field New Instructions */
    int vaes;            /* Vector AES (256/512-bit) */
    int vpclmulqdq;      /* Vector PCLMULQDQ (256/512-bit) */
    int avx512vnni;      /* AVX-512 Vector Neural Network Instructions */
    int avx512bitalg;    /* AVX-512 Bit Algorithms */
    int tme;             /* Total Memory Encryption */
    int avx512vpopcntdq; /* AVX-512 VPOPCNTD/VPOPCNTQ */
    int la57;            /* 5-level paging (57-bit linear addresses) */
    int rdpid;           /* RDPID — Read Processor ID */
    int kl;              /* Key Locker */
    int cldemote;        /* CLDEMOTE — Cache Line Demote */
    int movdiri;         /* MOVDIRI — Direct Store doubleword */
    int movdir64b;       /* MOVDIR64B — Direct Store 64 bytes */
    int enqcmd;          /* ENQCMD — Enqueue Stores */
    int sgx_lc;          /* SGX Launch Configuration */
    int pks;             /* Protection Keys for Supervisor pages */

    /* --- Leaf 7, subleaf 0, EDX --- */
    int avx512_4vnniw;   /* AVX-512 4-register VNNIW (Xeon Phi) */
    int avx512_4fmaps;   /* AVX-512 4-register FMA (Xeon Phi) */
    int fsrm;            /* Fast Short REP MOVSB */
    int avx512vp2intersect; /* AVX-512 VP2INTERSECT (Tiger Lake) */
    int srbds_ctrl;      /* SRBDS mitigation MSR */
    int md_clear;        /* VERW clears CPU buffers (MDS mitigation) */
    int rtm_always_abort;
    int tsx_force_abort;
    int serialize;       /* SERIALIZE instruction */
    int hybrid;          /* Hybrid CPU (P-core + E-core, Alder Lake+) */
    int tsxldtrk;        /* TSX suspend load address tracking */
    int pconfig;         /* PCONFIG (platform config for TME) */
    int lbr;             /* Architectural Last Branch Records */
    int cet_ibt;         /* Control-flow Enforcement: Indirect Branch Tracking */
    int amx_bf16;        /* AMX BFloat16 (Sapphire Rapids) */
    int avx512fp16;      /* AVX-512 FP16 (Sapphire Rapids) */
    int amx_tile;        /* AMX Tile architecture (Sapphire Rapids) */
    int amx_int8;        /* AMX INT8 (Sapphire Rapids) */
    int ibrs_ibpb;       /* Indirect Branch Restricted Speculation */
    int stibp;           /* Single Thread Indirect Branch Predictors */
    int l1d_flush;       /* L1D_FLUSH MSR (Meltdown mitigation) */
    int ia32_arch_cap;   /* IA32_ARCH_CAPABILITIES MSR */
    int ia32_core_cap;   /* IA32_CORE_CAPABILITIES MSR */
    int ssbd;            /* Speculative Store Bypass Disable (Spectre v4) */

    /* --- Leaf 7, subleaf 1, EAX --- */
    int sha512;          /* SHA-512 extensions */
    int sm3;             /* SM3 hash (Chinese standard) */
    int sm4;             /* SM4 cipher (Chinese standard) */
    int rao_int;         /* Remote Atomic Operations */
    int avx_vnni;        /* AVX VNNI (VEX-encoded, 128/256-bit) */
    int avx512bf16;      /* AVX-512 BFloat16 (Cooper Lake) */
    int lass;            /* Linear Address Space Separation */
    int cmpccxadd;       /* CMPccXADD instructions */
    int amx_fp16;        /* AMX FP16 (Granite Rapids) */
    int hreset;          /* HRESET instruction */
    int avx_ifma;        /* AVX IFMA (VEX-encoded, 256-bit) */
    int lam;             /* Linear Address Masking */
    int msrlist;         /* RDMSRLIST/WRMSRLIST */

    /* --- Leaf 7, subleaf 1, EBX --- */
    int ia32_ppin;       /* Protected Processor Inventory Number */

    /* --- Leaf 7, subleaf 1, EDX --- */
    int avx_vnni_int8;   /* AVX VNNI INT8 */
    int avx_ne_convert;  /* AVX NE CONVERT (non-exception FP16/BF16) */
    int avx_vnni_int16;  /* AVX VNNI INT16 */
    int prefetchi;       /* PREFETCHIT0/PREFETCHIT1 */
    int user_msr;        /* User-mode MSR access */
    int avx10;           /* AVX10 converged ISA (Granite Rapids) */
    int apx_f;           /* APX Foundation — Extended GPR (32 regs) */

    /* --- Leaf 0x80000001 ECX (AMD extended / shared) --- */
    int lahf_lm;         /* LAHF/SAHF in 64-bit mode */
    int cmp_legacy;      /* Core Multi-Processing legacy mode (AMD) */
    int svm;             /* AMD-V (Virtualization) */
    int extapic;         /* Extended APIC space (AMD) */
    int cr8_legacy;      /* CR8 in 32-bit mode (AMD) */
    int abm, lzcnt;      /* Advanced Bit Manipulation: LZCNT+POPCNT (AMD) */
    int sse4a;           /* SSE4a (AMD only) */
    int misalignsse;     /* Misaligned SSE mode (AMD) */
    int prefetchw;       /* PREFETCHW (3DNow! prefetch) */
    int osvw;            /* OS Visible Workaround (AMD) */
    int ibs;             /* Instruction Based Sampling (AMD) */
    int xop;             /* XOP instructions (AMD Bulldozer) */
    int skinit;          /* SKINIT/STGI (AMD secure init) */
    int wdt;             /* Watchdog Timer (AMD) */
    int lwp;             /* Light Weight Profiling (AMD) */
    int fma4;            /* FMA4 — 4-operand FMA (AMD Bulldozer, deprecated) */
    int tce;             /* Translation Cache Extension (AMD) */
    int nodeid_msr;      /* NodeId MSR (AMD) */
    int tbm;             /* Trailing Bit Manipulation (AMD Piledriver) */
    int topoext;         /* Topology Extensions (AMD) */
    int perfctr_core;    /* Core Performance Counter Extensions (AMD) */
    int perfctr_nb;      /* NB Performance Counter Extensions (AMD) */
    int bpext;           /* Data Breakpoint Extension (AMD) */
    int ptsc;            /* Performance TSC (AMD) */
    int perfctr_llc;     /* LLC Performance Counter Extensions (AMD) */
    int mwaitx;          /* MONITORX/MWAITX (AMD Zen) */

    /* --- Leaf 0x80000001 EDX (AMD extended / shared) --- */
    int syscall;         /* SYSCALL/SYSRET (64-bit) */
    int mp;              /* MP capable */
    int nx;              /* No-Execute Page Protection (XD/NX bit) */
    int mmxext;          /* AMD MMX Extensions */
    int fxsr_opt;        /* FXSAVE/FXRSTOR optimizations (AMD) */
    int pdpe1gb;         /* 1GB pages (PDPE1GB) */
    int rdtscp;          /* RDTSCP instruction */
    int lm;              /* Long Mode (x86-64) */
    int _3dnowext;       /* 3DNow! Extensions (AMD) */
    int _3dnow;          /* 3DNow! (AMD, deprecated) */

    /* --- Leaf 0xD subleaf 1, EAX (XSAVE features) --- */
    int xsaveopt;        /* XSAVEOPT instruction */
    int xsavec;          /* XSAVEC and compacted XRSTOR */
    int xgetbv1;         /* XGETBV with ECX=1 */
    int xss;             /* XSAVES/XRSTORS and IA32_XSS MSR */

} CpuFeatures;

/* -------------------------------------------------------------------------
 * Detection
 * ------------------------------------------------------------------------- */

static inline CpuFeatures cpu_detect(void)
{
    CpuFeatures f;
    memset(&f, 0, sizeof(f));

    uint32_t eax, ebx, ecx, edx;
    uint32_t max_leaf, max_ext_leaf;

    /* --- Vendor string + max leaf --- */
    _cpuid(0, &eax, &ebx, &ecx, &edx);
    max_leaf = eax;
    memcpy(f.vendor + 0, &ebx, 4);
    memcpy(f.vendor + 4, &edx, 4);
    memcpy(f.vendor + 8, &ecx, 4);
    f.vendor[12] = '\0';
    f.is_intel = (memcmp(f.vendor, "GenuineIntel", 12) == 0);
    f.is_amd   = (memcmp(f.vendor, "AuthenticAMD", 12) == 0);

    /* --- Leaf 1 --- */
    if (max_leaf >= 1) {
        _cpuid(1, &eax, &ebx, &ecx, &edx);

        /* EDX */
        f.fpu    = (edx >>  0) & 1;
        f.vme    = (edx >>  1) & 1;
        f.de     = (edx >>  2) & 1;
        f.pse    = (edx >>  3) & 1;
        f.tsc    = (edx >>  4) & 1;
        f.msr    = (edx >>  5) & 1;
        f.pae    = (edx >>  6) & 1;
        f.mce    = (edx >>  7) & 1;
        f.cx8    = (edx >>  8) & 1;
        f.apic   = (edx >>  9) & 1;
        f.sep    = (edx >> 11) & 1;
        f.mtrr   = (edx >> 12) & 1;
        f.pge    = (edx >> 13) & 1;
        f.mca    = (edx >> 14) & 1;
        f.cmov   = (edx >> 15) & 1;
        f.pat    = (edx >> 16) & 1;
        f.pse36  = (edx >> 17) & 1;
        f.psn    = (edx >> 18) & 1;
        f.clfsh  = (edx >> 19) & 1;
        f.ds     = (edx >> 21) & 1;
        f.acpi   = (edx >> 22) & 1;
        f.mmx    = (edx >> 23) & 1;
        f.fxsr   = (edx >> 24) & 1;
        f.sse    = (edx >> 25) & 1;
        f.sse2   = (edx >> 26) & 1;
        f.ss     = (edx >> 27) & 1;
        f.htt    = (edx >> 28) & 1;
        f.tm     = (edx >> 29) & 1;
        f.pbe    = (edx >> 31) & 1;

        /* ECX */
        f.sse3         = (ecx >>  0) & 1;
        f.pclmulqdq    = (ecx >>  1) & 1;
        f.dtes64       = (ecx >>  2) & 1;
        f.monitor      = (ecx >>  3) & 1;
        f.ds_cpl       = (ecx >>  4) & 1;
        f.vmx          = (ecx >>  5) & 1;
        f.smx          = (ecx >>  6) & 1;
        f.est          = (ecx >>  7) & 1;
        f.tm2          = (ecx >>  8) & 1;
        f.ssse3        = (ecx >>  9) & 1;
        f.cnxt_id      = (ecx >> 10) & 1;
        f.sdbg         = (ecx >> 11) & 1;
        f.fma          = (ecx >> 12) & 1;
        f.cx16         = (ecx >> 13) & 1;
        f.xtpr         = (ecx >> 14) & 1;
        f.pdcm         = (ecx >> 15) & 1;
        f.pcid         = (ecx >> 17) & 1;
        f.dca          = (ecx >> 18) & 1;
        f.sse4_1       = (ecx >> 19) & 1;
        f.sse4_2       = (ecx >> 20) & 1;
        f.x2apic       = (ecx >> 21) & 1;
        f.movbe        = (ecx >> 22) & 1;
        f.popcnt       = (ecx >> 23) & 1;
        f.tsc_deadline = (ecx >> 24) & 1;
        f.aes          = (ecx >> 25) & 1;
        f.xsave        = (ecx >> 26) & 1;
        f.osxsave      = (ecx >> 27) & 1;
        f.avx          = (ecx >> 28) & 1;
        f.f16c         = (ecx >> 29) & 1;
        f.rdrnd        = (ecx >> 30) & 1;
        f.hypervisor   = (ecx >> 31) & 1;
    }

    /* --- Leaf 7 subleaf 0 --- */
    if (max_leaf >= 7) {
        _cpuidex(7, 0, &eax, &ebx, &ecx, &edx);
        uint32_t max_subleaf_7 = eax;

        /* EBX */
        f.fsgsbase          = (ebx >>  0) & 1;
        f.ia32_tsc_adjust   = (ebx >>  1) & 1;
        f.sgx               = (ebx >>  2) & 1;
        f.bmi1              = (ebx >>  3) & 1;
        f.hle               = (ebx >>  4) & 1;
        f.avx2              = (ebx >>  5) & 1;
        f.fdp_excptn_only   = (ebx >>  6) & 1;
        f.smep              = (ebx >>  7) & 1;
        f.bmi2              = (ebx >>  8) & 1;
        f.erms              = (ebx >>  9) & 1;
        f.invpcid           = (ebx >> 10) & 1;
        f.rtm               = (ebx >> 11) & 1;
        f.mpx               = (ebx >> 14) & 1;
        f.avx512f           = (ebx >> 16) & 1;
        f.avx512dq          = (ebx >> 17) & 1;
        f.rdseed            = (ebx >> 18) & 1;
        f.adx               = (ebx >> 19) & 1;
        f.smap              = (ebx >> 20) & 1;
        f.avx512ifma        = (ebx >> 21) & 1;
        f.clflushopt        = (ebx >> 23) & 1;
        f.clwb              = (ebx >> 24) & 1;
        f.intel_pt          = (ebx >> 25) & 1;
        f.avx512pf          = (ebx >> 26) & 1;
        f.avx512er          = (ebx >> 27) & 1;
        f.avx512cd          = (ebx >> 28) & 1;
        f.sha               = (ebx >> 29) & 1;
        f.avx512bw          = (ebx >> 30) & 1;
        f.avx512vl          = (ebx >> 31) & 1;

        /* ECX */
        f.prefetchwt1       = (ecx >>  0) & 1;
        f.avx512vbmi        = (ecx >>  1) & 1;
        f.umip              = (ecx >>  2) & 1;
        f.pku               = (ecx >>  3) & 1;
        f.ospke             = (ecx >>  4) & 1;
        f.waitpkg           = (ecx >>  5) & 1;
        f.avx512vbmi2       = (ecx >>  6) & 1;
        f.cet_ss            = (ecx >>  7) & 1;
        f.gfni              = (ecx >>  8) & 1;
        f.vaes              = (ecx >>  9) & 1;
        f.vpclmulqdq        = (ecx >> 10) & 1;
        f.avx512vnni        = (ecx >> 11) & 1;
        f.avx512bitalg      = (ecx >> 12) & 1;
        f.tme               = (ecx >> 13) & 1;
        f.avx512vpopcntdq   = (ecx >> 14) & 1;
        f.la57              = (ecx >> 16) & 1;
        f.rdpid             = (ecx >> 22) & 1;
        f.kl                = (ecx >> 23) & 1;
        f.cldemote          = (ecx >> 25) & 1;
        f.movdiri           = (ecx >> 27) & 1;
        f.movdir64b         = (ecx >> 28) & 1;
        f.enqcmd            = (ecx >> 29) & 1;
        f.sgx_lc            = (ecx >> 30) & 1;
        f.pks               = (ecx >> 31) & 1;

        /* EDX */
        f.avx512_4vnniw        = (edx >>  2) & 1;
        f.avx512_4fmaps        = (edx >>  3) & 1;
        f.fsrm                 = (edx >>  4) & 1;
        f.avx512vp2intersect   = (edx >>  8) & 1;
        f.srbds_ctrl           = (edx >>  9) & 1;
        f.md_clear             = (edx >> 10) & 1;
        f.rtm_always_abort     = (edx >> 11) & 1;
        f.tsx_force_abort      = (edx >> 13) & 1;
        f.serialize            = (edx >> 14) & 1;
        f.hybrid               = (edx >> 15) & 1;
        f.tsxldtrk             = (edx >> 16) & 1;
        f.pconfig              = (edx >> 18) & 1;
        f.lbr                  = (edx >> 19) & 1;
        f.cet_ibt              = (edx >> 20) & 1;
        f.amx_bf16             = (edx >> 22) & 1;
        f.avx512fp16           = (edx >> 23) & 1;
        f.amx_tile             = (edx >> 24) & 1;
        f.amx_int8             = (edx >> 25) & 1;
        f.ibrs_ibpb            = (edx >> 26) & 1;
        f.stibp                = (edx >> 27) & 1;
        f.l1d_flush            = (edx >> 28) & 1;
        f.ia32_arch_cap        = (edx >> 29) & 1;
        f.ia32_core_cap        = (edx >> 30) & 1;
        f.ssbd                 = (edx >> 31) & 1;

        /* --- Leaf 7 subleaf 1 --- */
        if (max_subleaf_7 >= 1) {
            _cpuidex(7, 1, &eax, &ebx, &ecx, &edx);

            /* EAX */
            f.sha512      = (eax >>  0) & 1;
            f.sm3         = (eax >>  1) & 1;
            f.sm4         = (eax >>  2) & 1;
            f.rao_int     = (eax >>  3) & 1;
            f.avx_vnni    = (eax >>  4) & 1;
            f.avx512bf16  = (eax >>  5) & 1;
            f.lass        = (eax >>  6) & 1;
            f.cmpccxadd   = (eax >>  7) & 1;
            f.amx_fp16    = (eax >> 21) & 1;
            f.hreset      = (eax >> 22) & 1;
            f.avx_ifma    = (eax >> 23) & 1;
            f.lam         = (eax >> 26) & 1;
            f.msrlist     = (eax >> 27) & 1;

            /* EBX */
            f.ia32_ppin   = (ebx >>  0) & 1;

            /* EDX */
            f.avx_vnni_int8   = (edx >>  4) & 1;
            f.avx_ne_convert  = (edx >>  5) & 1;
            f.avx_vnni_int16  = (edx >> 10) & 1;
            f.prefetchi       = (edx >> 14) & 1;
            f.user_msr        = (edx >> 15) & 1;
            f.avx10           = (edx >> 19) & 1;
            f.apx_f           = (edx >> 21) & 1;
        }
    }

    /* --- Leaf 0xD subleaf 1 (XSAVE) --- */
    if (max_leaf >= 0xD) {
        _cpuidex(0xD, 1, &eax, &ebx, &ecx, &edx);
        f.xsaveopt = (eax >> 0) & 1;
        f.xsavec   = (eax >> 1) & 1;
        f.xgetbv1  = (eax >> 2) & 1;
        f.xss      = (eax >> 3) & 1;
    }

    /* --- Extended leaves --- */
    _cpuid(0x80000000u, &eax, &ebx, &ecx, &edx);
    max_ext_leaf = eax;

    /* --- Leaf 0x80000001 --- */
    if (max_ext_leaf >= 0x80000001u) {
        _cpuid(0x80000001u, &eax, &ebx, &ecx, &edx);

        /* ECX */
        f.lahf_lm      = (ecx >>  0) & 1;
        f.cmp_legacy   = (ecx >>  1) & 1;
        f.svm          = (ecx >>  2) & 1;
        f.extapic      = (ecx >>  3) & 1;
        f.cr8_legacy   = (ecx >>  4) & 1;
        f.abm = f.lzcnt= (ecx >>  5) & 1;  /* LZCNT */
        f.sse4a        = (ecx >>  6) & 1;
        f.misalignsse  = (ecx >>  7) & 1;
        f.prefetchw    = (ecx >>  8) & 1;
        f.osvw         = (ecx >>  9) & 1;
        f.ibs          = (ecx >> 10) & 1;
        f.xop          = (ecx >> 11) & 1;
        f.skinit       = (ecx >> 12) & 1;
        f.wdt          = (ecx >> 13) & 1;
        f.lwp          = (ecx >> 15) & 1;
        f.fma4         = (ecx >> 16) & 1;
        f.tce          = (ecx >> 17) & 1;
        f.nodeid_msr   = (ecx >> 19) & 1;
        f.tbm          = (ecx >> 21) & 1;
        f.topoext      = (ecx >> 22) & 1;
        f.perfctr_core = (ecx >> 23) & 1;
        f.perfctr_nb   = (ecx >> 24) & 1;
        f.bpext        = (ecx >> 26) & 1;
        f.ptsc         = (ecx >> 27) & 1;
        f.perfctr_llc  = (ecx >> 28) & 1;
        f.mwaitx       = (ecx >> 29) & 1;

        /* EDX */
        f.syscall   = (edx >> 11) & 1;
        f.mp        = (edx >> 19) & 1;
        f.nx        = (edx >> 20) & 1;
        f.mmxext    = (edx >> 22) & 1;
        f.fxsr_opt  = (edx >> 25) & 1;
        f.pdpe1gb   = (edx >> 26) & 1;
        f.rdtscp    = (edx >> 27) & 1;
        f.lm        = (edx >> 29) & 1;
        f._3dnowext = (edx >> 30) & 1;
        f._3dnow    = (edx >> 31) & 1;
    }

    /* --- Brand string (leaves 0x80000002..4) --- */
    if (max_ext_leaf >= 0x80000004u) {
        uint32_t *b = (uint32_t *)f.brand;
        _cpuid(0x80000002u, &b[0],  &b[1],  &b[2],  &b[3]);
        _cpuid(0x80000003u, &b[4],  &b[5],  &b[6],  &b[7]);
        _cpuid(0x80000004u, &b[8],  &b[9],  &b[10], &b[11]);
        f.brand[48] = '\0';
    }

    return f;
}

