/* =========================================================================
 * Cache topology
 * =========================================================================
 *
 * Sources:
 *   Intel: CPUID leaf 4 (subleaf 0,1,2,...) — structured cache params
 *   AMD:   CPUID leaf 0x8000001D            — same format as Intel leaf 4
 *          CPUID leaf 0x80000005            — L1 TLB/cache (legacy)
 *          CPUID leaf 0x80000006            — L2/L3 (legacy, always valid)
 *   Both:  CPUID leaf 2 (Intel legacy descriptors, mostly ignored here)
 *          CPUID leaf 0x80000006 EDX bits 18..31 — L3 size in 512KB units
 */

#define CPU_CACHE_MAX_LEVELS 8  /* практический максимум — 4, берём с запасом */

typedef enum {
    CPU_CACHE_TYPE_NULL        = 0,  /* нет кэша на этом subleaf */
    CPU_CACHE_TYPE_DATA        = 1,
    CPU_CACHE_TYPE_INSTRUCTION = 2,
    CPU_CACHE_TYPE_UNIFIED     = 3
} CpuCacheType;

typedef struct {
    CpuCacheType type;           /* Data / Instruction / Unified */
    int          level;          /* 1, 2, 3, ... */
    uint32_t     size_bytes;     /* полный размер кэша в байтах */
    uint32_t     line_size;      /* размер кэш-линии в байтах */
    uint32_t     sets;           /* число множеств (sets) */
    uint32_t     ways;           /* ассоциативность (ways) */
    uint32_t     partitions;     /* число физических линий на путь */
    int          self_init;      /* самоинициализируемый (не требует SW init) */
    int          fully_assoc;    /* полностью ассоциативный */
    int          inclusive;      /* inclusive (данные L1 есть и в L2/L3) */
    int          complex_index;  /* complex cache indexing (Intel: "no direct map guarantee") */
    uint32_t     max_threads_sharing;  /* макс. логических ядер, разделяющих этот кэш */
    uint32_t     max_cores_package;    /* макс. физических ядер в пакете */
} CpuCacheLevel;

typedef struct {
    /* Кэши инструкций, данных, унифицированные (L1..L3+) */
    CpuCacheLevel levels[CPU_CACHE_MAX_LEVELS];
    int           count;          /* число заполненных элементов levels[] */

    /* Размер кэш-линии для prefetch (из leaf 1 EDX или leaf 0x80000006) */
    uint32_t      clflush_line_size;   /* байт, из leaf 1 EBX[15:8] * 8 */

    /* --- TLB --- */
    /* L1 инструкционный TLB */
    uint32_t      l1i_tlb_4k_entries;
    uint32_t      l1i_tlb_4k_ways;
    uint32_t      l1i_tlb_2m_entries;
    uint32_t      l1i_tlb_2m_ways;
    uint32_t      l1i_tlb_4m_entries;
    uint32_t      l1i_tlb_4m_ways;
    uint32_t      l1i_tlb_1g_entries;
    uint32_t      l1i_tlb_1g_ways;
    /* L1 данных TLB */
    uint32_t      l1d_tlb_4k_entries;
    uint32_t      l1d_tlb_4k_ways;
    uint32_t      l1d_tlb_2m_entries;
    uint32_t      l1d_tlb_2m_ways;
    uint32_t      l1d_tlb_4m_entries;
    uint32_t      l1d_tlb_4m_ways;
    uint32_t      l1d_tlb_1g_entries;
    uint32_t      l1d_tlb_1g_ways;
    /* L2 унифицированный TLB */
    uint32_t      l2_tlb_4k_entries;
    uint32_t      l2_tlb_4k_ways;
    uint32_t      l2_tlb_2m_entries;
    uint32_t      l2_tlb_2m_ways;
    uint32_t      l2_tlb_4m_entries;
    uint32_t      l2_tlb_4m_ways;

    /* --- Prefetch --- */
    uint32_t      prefetch_line_size;  /* из leaf 0x80000005 EBX (AMD) */
} CpuCacheInfo;

/* Декодер ассоциативности по AMD-коду (leaf 0x80000006) */
static inline uint32_t _amd_assoc_decode(uint32_t code)
{
    /* AMD BKDG: значения поля Assoc в leaf 0x80000006 */
    switch (code) {
        case 0x0: return 0;   /* disabled */
        case 0x1: return 1;
        case 0x2: return 2;
        case 0x4: return 4;
        case 0x6: return 8;
        case 0x8: return 16;
        case 0xA: return 32;
        case 0xB: return 48;
        case 0xC: return 64;
        case 0xD: return 96;
        case 0xE: return 128;
        case 0xF: return 0xFF; /* fully associative */
        default:  return code;
    }
}

static inline CpuCacheInfo cpu_cache_detect(void)
{
    CpuCacheInfo ci;
    memset(&ci, 0, sizeof(ci));

    uint32_t eax, ebx, ecx, edx;
    uint32_t max_leaf, max_ext_leaf;

    /* max leaf */
    _cpuid(0, &max_leaf, &ebx, &ecx, &edx);
    _cpuid(0x80000000u, &max_ext_leaf, &ebx, &ecx, &edx);

    /* Vendor */
    uint32_t vebx, vecx, vedx;
    _cpuid(0, &eax, &vebx, &vecx, &vedx);
    char vendor[13];
    memcpy(vendor + 0, &vebx, 4);
    memcpy(vendor + 4, &vedx, 4);
    memcpy(vendor + 8, &vecx, 4);
    vendor[12] = '\0';
    int is_intel = (memcmp(vendor, "GenuineIntel", 12) == 0);
    int is_amd   = (memcmp(vendor, "AuthenticAMD", 12) == 0);

    /* --- CLFLUSH line size из leaf 1 EBX[15:8] --- */
    if (max_leaf >= 1) {
        _cpuid(1, &eax, &ebx, &ecx, &edx);
        ci.clflush_line_size = ((ebx >> 8) & 0xFF) * 8;
    }

    /* -------------------------------------------------------------------------
     * Structured cache info: Intel leaf 4 / AMD leaf 0x8000001D
     * Формат EAX/EBX/ECX одинаковый для обоих.
     * ------------------------------------------------------------------------- */
    uint32_t struct_leaf = 0;
    if (is_intel && max_leaf >= 4)
        struct_leaf = 4;
    else if (is_amd && max_ext_leaf >= 0x8000001Du)
        struct_leaf = 0x8000001Du;

    if (struct_leaf) {
        for (uint32_t sub = 0; ci.count < CPU_CACHE_MAX_LEVELS; sub++) {
            _cpuidex(struct_leaf, sub, &eax, &ebx, &ecx, &edx);

            uint32_t ctype = eax & 0x1F;
            if (ctype == 0) break;   /* нет больше кэшей */

            CpuCacheLevel *lv = &ci.levels[ci.count++];
            lv->type  = (CpuCacheType)ctype;
            lv->level = (eax >> 5) & 0x7;

            lv->self_init     = (eax >> 8)  & 1;
            lv->fully_assoc   = (eax >> 9)  & 1;
            /* EAX[25:14] — max logical processors sharing this cache (0-based) */
            lv->max_threads_sharing = ((eax >> 14) & 0xFFF) + 1;
            /* EAX[31:26] — max cores in physical package (0-based) */
            lv->max_cores_package   = ((eax >> 26) & 0x3F) + 1;

            lv->line_size  = (ebx & 0xFFF) + 1;          /* EBX[11:0] */
            lv->partitions = ((ebx >> 12) & 0x3FF) + 1;  /* EBX[21:12] */
            lv->ways       = ((ebx >> 22) & 0x3FF) + 1;  /* EBX[31:22] */
            lv->sets       = ecx + 1;                    /* ECX */

            lv->size_bytes = lv->ways * lv->partitions * lv->line_size * lv->sets;

            /* EDX */
            lv->inclusive     = (edx >> 1) & 1;
            lv->complex_index = (edx >> 2) & 1;
        }
    }

    /* -------------------------------------------------------------------------
     * AMD legacy: leaf 0x80000005 — L1 TLB + L1 cache
     * ------------------------------------------------------------------------- */
    if (is_amd && max_ext_leaf >= 0x80000005u) {
        _cpuid(0x80000005u, &eax, &ebx, &ecx, &edx);

        /* EAX: L1 TLB для 2MB/4MB страниц */
        ci.l1i_tlb_2m_ways    = (eax >> 24) & 0xFF;
        ci.l1i_tlb_2m_entries = (eax >> 16) & 0xFF;
        ci.l1d_tlb_2m_ways    = (eax >>  8) & 0xFF;
        ci.l1d_tlb_2m_entries = (eax >>  0) & 0xFF;
        /* для 4MB совпадает с 2MB полем (половина entries) */
        ci.l1i_tlb_4m_ways    = ci.l1i_tlb_2m_ways;
        ci.l1i_tlb_4m_entries = ci.l1i_tlb_2m_entries / 2;
        ci.l1d_tlb_4m_ways    = ci.l1d_tlb_2m_ways;
        ci.l1d_tlb_4m_entries = ci.l1d_tlb_2m_entries / 2;

        /* EBX: L1 TLB для 4KB страниц */
        ci.l1i_tlb_4k_ways    = (ebx >> 24) & 0xFF;
        ci.l1i_tlb_4k_entries = (ebx >> 16) & 0xFF;
        ci.l1d_tlb_4k_ways    = (ebx >>  8) & 0xFF;
        ci.l1d_tlb_4k_entries = (ebx >>  0) & 0xFF;

        /* ECX: L1 Data cache */
        /* (если struct_leaf не сработал, добавляем L1D вручную) */
        if (struct_leaf == 0 && ci.count < CPU_CACHE_MAX_LEVELS) {
            CpuCacheLevel *lv = &ci.levels[ci.count++];
            lv->type       = CPU_CACHE_TYPE_DATA;
            lv->level      = 1;
            lv->size_bytes = ((ecx >> 24) & 0xFF) * 1024;
            lv->ways       = (ecx >> 16) & 0xFF;
            lv->sets       = (ecx >>  8) & 0xFF;
            lv->line_size  = ecx & 0xFF;
        }
        ci.prefetch_line_size = (ebx >> 0) & 0xFF; /* EBX[7:0] иногда prefetch size */

        /* EDX: L1 Instruction cache */
        if (struct_leaf == 0 && ci.count < CPU_CACHE_MAX_LEVELS) {
            CpuCacheLevel *lv = &ci.levels[ci.count++];
            lv->type       = CPU_CACHE_TYPE_INSTRUCTION;
            lv->level      = 1;
            lv->size_bytes = ((edx >> 24) & 0xFF) * 1024;
            lv->ways       = (edx >> 16) & 0xFF;
            lv->sets       = (edx >>  8) & 0xFF;
            lv->line_size  = edx & 0xFF;
        }
    }

    /* -------------------------------------------------------------------------
     * AMD/shared legacy: leaf 0x80000006 — L2 + L3
     * ------------------------------------------------------------------------- */
    if (max_ext_leaf >= 0x80000006u) {
        _cpuid(0x80000006u, &eax, &ebx, &ecx, &edx);

        /* EAX: L2 TLB для 2MB/4MB страниц */
        ci.l2_tlb_2m_ways    = (eax >> 28) & 0xF;
        ci.l2_tlb_2m_entries = (eax >> 16) & 0xFFF;
        ci.l2_tlb_4m_ways    = ci.l2_tlb_2m_ways;
        ci.l2_tlb_4m_entries = ci.l2_tlb_2m_entries / 2;

        /* EBX: L2 TLB для 4KB страниц */
        ci.l2_tlb_4k_ways    = (ebx >> 28) & 0xF;
        ci.l2_tlb_4k_entries = (ebx >> 16) & 0xFFF;

        /* ECX: L2 Unified cache */
        if (struct_leaf == 0 && ci.count < CPU_CACHE_MAX_LEVELS) {
            uint32_t l2_size_kb = (ecx >> 16) & 0xFFFF;
            uint32_t l2_assoc   = _amd_assoc_decode((ecx >> 12) & 0xF);
            uint32_t l2_line    = ecx & 0xFF;
            if (l2_size_kb > 0) {
                CpuCacheLevel *lv = &ci.levels[ci.count++];
                lv->type       = CPU_CACHE_TYPE_UNIFIED;
                lv->level      = 2;
                lv->size_bytes = l2_size_kb * 1024;
                lv->ways       = l2_assoc;
                lv->line_size  = l2_line;
                lv->fully_assoc = (l2_assoc == 0xFF);
            }
        }

        /* EDX: L3 Unified cache — размер в 512KB единицах */
        uint32_t l3_size_512k = (edx >> 18) & 0x3FFF;
        uint32_t l3_assoc     = _amd_assoc_decode((edx >> 12) & 0xF);
        uint32_t l3_line      = edx & 0xFF;
        if (l3_size_512k > 0 && struct_leaf == 0 && ci.count < CPU_CACHE_MAX_LEVELS) {
            CpuCacheLevel *lv = &ci.levels[ci.count++];
            lv->type       = CPU_CACHE_TYPE_UNIFIED;
            lv->level      = 3;
            lv->size_bytes = l3_size_512k * 512 * 1024;
            lv->ways       = l3_assoc;
            lv->line_size  = l3_line;
            lv->fully_assoc = (l3_assoc == 0xFF);
        }
    }

    /* -------------------------------------------------------------------------
     * AMD Zen: leaf 0x80000019 — L1/L2 TLB для 1GB страниц
     * ------------------------------------------------------------------------- */
    if (is_amd && max_ext_leaf >= 0x80000019u) {
        _cpuid(0x80000019u, &eax, &ebx, &ecx, &edx);
        /* EAX: L1 TLB 1GB */
        ci.l1i_tlb_1g_ways    = (eax >> 28) & 0xF;
        ci.l1i_tlb_1g_entries = (eax >> 16) & 0xFFF;
        ci.l1d_tlb_1g_ways    = (eax >> 12) & 0xF;
        ci.l1d_tlb_1g_entries = (eax >>  0) & 0xFFF;
    }

    return ci;
}

/* -------------------------------------------------------------------------
 * Cache type string helper
 * ------------------------------------------------------------------------- */
static inline const char *cpu_cache_type_str(CpuCacheType t)
{
    switch (t) {
        case CPU_CACHE_TYPE_DATA:        return "Data";
        case CPU_CACHE_TYPE_INSTRUCTION: return "Instruction";
        case CPU_CACHE_TYPE_UNIFIED:     return "Unified";
        default:                         return "Unknown";
    }
}

/* -------------------------------------------------------------------------
 * Print cache info
 * ------------------------------------------------------------------------- */
#ifdef CPU_FEATURES_PRINT
#include <stdio.h>

static inline void _fmt_size(uint32_t bytes, char *buf, int bufsz)
{
    if (bytes >= 1024*1024)
        snprintf(buf, (size_t)bufsz, "%u MB", bytes / (1024*1024));
    else if (bytes >= 1024)
        snprintf(buf, (size_t)bufsz, "%u KB", bytes / 1024);
    else
        snprintf(buf, (size_t)bufsz, "%u B", bytes);
}

static inline void cpu_cache_print(const CpuCacheInfo *ci)
{
    char sz[32];
    printf("=== Cache topology ===\n");
    printf("CLFLUSH line size : %u bytes\n\n", ci->clflush_line_size);

    for (int i = 0; i < ci->count; i++) {
        const CpuCacheLevel *lv = &ci->levels[i];
        _fmt_size(lv->size_bytes, sz, sizeof(sz));
        printf("L%d %-11s  size=%-8s  line=%2uB  ways=",
               lv->level, cpu_cache_type_str(lv->type),
               sz, lv->line_size);
        if (lv->fully_assoc)
            printf("fully-assoc");
        else
            printf("%u", lv->ways);
        printf("  sets=%u  partitions=%u\n",
               lv->sets, lv->partitions ? lv->partitions : 1);
        if (lv->max_threads_sharing > 1)
            printf("   shared by %u logical threads, pkg_cores=%u\n",
                   lv->max_threads_sharing, lv->max_cores_package);
        if (lv->inclusive)     printf("   [inclusive]\n");
        if (lv->complex_index) printf("   [complex indexing]\n");
        if (lv->self_init)     printf("   [self-initializing]\n");
    }

    /* TLB */
    printf("\n=== TLB ===\n");
    if (ci->l1d_tlb_4k_entries)
        printf("L1D TLB 4K  : %u entries, %u-way\n",
               ci->l1d_tlb_4k_entries, ci->l1d_tlb_4k_ways);
    if (ci->l1d_tlb_2m_entries)
        printf("L1D TLB 2M  : %u entries, %u-way\n",
               ci->l1d_tlb_2m_entries, ci->l1d_tlb_2m_ways);
    if (ci->l1d_tlb_4m_entries)
        printf("L1D TLB 4M  : %u entries, %u-way\n",
               ci->l1d_tlb_4m_entries, ci->l1d_tlb_4m_ways);
    if (ci->l1d_tlb_1g_entries)
        printf("L1D TLB 1G  : %u entries, %u-way\n",
               ci->l1d_tlb_1g_entries, ci->l1d_tlb_1g_ways);
    if (ci->l1i_tlb_4k_entries)
        printf("L1I TLB 4K  : %u entries, %u-way\n",
               ci->l1i_tlb_4k_entries, ci->l1i_tlb_4k_ways);
    if (ci->l1i_tlb_2m_entries)
        printf("L1I TLB 2M  : %u entries, %u-way\n",
               ci->l1i_tlb_2m_entries, ci->l1i_tlb_2m_ways);
    if (ci->l1i_tlb_1g_entries)
        printf("L1I TLB 1G  : %u entries, %u-way\n",
               ci->l1i_tlb_1g_entries, ci->l1i_tlb_1g_ways);
    if (ci->l2_tlb_4k_entries)
        printf("L2  TLB 4K  : %u entries, %u-way\n",
               ci->l2_tlb_4k_entries, ci->l2_tlb_4k_ways);
    if (ci->l2_tlb_2m_entries)
        printf("L2  TLB 2M  : %u entries, %u-way\n",
               ci->l2_tlb_2m_entries, ci->l2_tlb_2m_ways);
}
#endif /* CPU_FEATURES_PRINT */